@Test
@Transactional
void 재고감소_성공() {
    Book book = 책만들기("JPA", 10000, 10);
    em.persist(book);
    em.flush();

    book.removeStock(3);
    em.flush();
}

#   Hibernate: select next value for item_seq
#   Hibernate: insert into item (...) values (?, ?, ?, ?, ?, 'B', ?)
#   binding parameter [3] as [INTEGER] - [10]

#   Hibernate: 
#       update item set name=?, price=?, stock_quantity=?, author=?, isbn=?
#       where item_id=?
#   binding parameter [3] as [INTEGER] - [7]

# --- 재고가 모자랄 때 ---

@Test
@Transactional
void 재고감소_실패() {
    Book book = 책만들기("JPA", 10000, 10);
    em.persist(book);
    em.flush();

    assertThatThrownBy(() -> book.removeStock(20))
            .isInstanceOf(NotEnoughStockException.class)
            .hasMessage("need more stock");
}

#   Hibernate: select next value for item_seq
#   Hibernate: insert into item (...) values (?, ?, ?, ?, ?, 'B', ?)

#   NotEnoughStockException: need more stock

#   (update 가 없다)

#   stockQuantity 를 안 바꿨으니 변경 감지할 것이 없다

#   PASSED

# --- 서비스를 통해 부르면 ---

orderService.order(memberId, itemId, 20);

#   Creating new transaction with name [OrderService.order]

#   Hibernate: select ... from member m1_0 where m1_0.member_id=?
#   Hibernate: select ... from item i1_0 where i1_0.item_id=?

#   NotEnoughStockException: need more stock

#   Completing transaction for [OrderService.order] after exception:
#     jpabook.jpashop.exception.NotEnoughStockException: need more stock
#   Initiating transaction rollback
#   Rolling back JPA transaction on EntityManager [SessionImpl@1]

#   (insert 가 하나도 안 나갔다)

select count(*) from orders;
#   -> 0

